def operate(data):
    if not data[1] in "+-*//%":
        return "Error"
    else:
        num1 = float(data[0])
        num2 = float(data[2])

        if data[1] == "+":
            return num1+num2
        elif data[1] == "-":
            return num1-num2
        elif data[1] == "*":
            return num1*num2
        elif data[1] == "/":
            try:
                return num1/num2
            except ZeroDivisionError:
                return "zero"
        elif data[1] == "//":
            try:
                return num1//num2
            except ZeroDivisionError:
                return "zero"
        elif data[1] == "%":
            try:
                return num1%num2
            except ZeroDivisionError:
                return "zero"

